using Orchestration.API.Engineering.Contracts;using Orchestration.API.Engineering.Services;using Microsoft.Extensions.Logging.Abstractions;using Xunit;
namespace Orchestration.API.Tests.Engineering;
public class EngineeringJobStoreTests{[Fact]public void TerminalJobCannotReturnToRunning(){var s=new EngineeringJobStore();var j=s.Create("r","c",EngineeringSource.Teamcenter,TimeSpan.FromMinutes(1));Assert.True(s.TryTransition(j.JobId,JobState.Success,EngineeringStage.Normalization,100,"done"));Assert.False(s.TryTransition(j.JobId,JobState.Extracting,EngineeringStage.Extraction,50,"late"));}[Fact]public void ProgressCannotDecrease(){var s=new EngineeringJobStore();var j=s.Create("r","c",EngineeringSource.Teamcenter,TimeSpan.FromMinutes(1));Assert.True(s.TryTransition(j.JobId,JobState.Extracting,EngineeringStage.Extraction,50,"half"));Assert.False(s.TryTransition(j.JobId,JobState.Extracting,EngineeringStage.Extraction,40,"back"));}[Fact]public void ActiveCancellationIsAccepted(){var s=new EngineeringJobStore();var j=s.Create("r","c",EngineeringSource.Teamcenter,TimeSpan.FromMinutes(1));using var r=new EngineeringCancellationRegistry(s);r.Register(j.JobId,CancellationToken.None,TimeSpan.FromMinutes(1));Assert.True(r.Cancel(j.JobId).Accepted);}}
